{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT strftime(time,'%H:%M:%S') ts, attr_k8s_pod_name pod, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-payment-service%' ORDER BY time LIMIT 12",
          "claim": "Payment pod restart counter goes from 0 to 1 at about 14:55:06 and stays at 1; normal period shows 0."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS failed_posts_without_payment_server_span FROM abnormal_traces c WHERE c.service_name='ts-inside-payment-service' AND c.span_name='POST' AND c.attr_status_code='Error' AND NOT EXISTS (SELECT 1 FROM abnormal_traces s WHERE s.parent_span_id=c.span_id)",
          "claim": "19 inside-payment POST calls failed with 503 after about 3.5s and never reached a payment-service server span."
        },
        {
          "kind": "log",
          "sql": "SELECT count(*) AS connection_refused_severe FROM abnormal_logs WHERE service_name='ts-inside-payment-service' AND level='SEVERE' AND message LIKE '%Connection refused%'",
          "claim": "Inside-payment logs SEVERE 503 exceptions with 'Connection refused' while the payment pod was restarting."
        },
        {
          "kind": "metric",
          "sql": "SELECT strftime(time,'%H:%M:%S') ts, round(value,2) cpu FROM abnormal_metrics WHERE service_name='ts-payment-service' AND metric='container.memory.rss' ORDER BY time LIMIT 20",
          "claim": "Payment container RSS drops from about 2 GB to about 273 MB at the restart, then regrows to normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-payment-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.attr_status_code cstatus, round(c.duration/1e6,1) client_ms, s.service_name callee, round(s.duration/1e6,1) server_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='ts-inside-payment-service' AND c.span_name='POST' ORDER BY c.time LIMIT 30",
          "claim": "Inside-payment POSTs during the restart window fail or take about 3.5s; later POSTs to payment take about 20ms."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('ts-inside-payment-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Inside-payment server p95 rises to about 3.6s with 19 errors, and ui-dashboard requests route through it."
        }
      ]
    }
  ]
